"""Retry post-commit private file removal without retaining deleted user data."""
import logging
from pathlib import Path
from app.services import source_images

logger = logging.getLogger(__name__)

def queue_dir() -> Path:
    root = source_images.ROOT.resolve()
    queue = root / ".deletion-pending"
    if queue.is_symlink() or queue.resolve().parent != root:
        raise ValueError("Invalid cleanup queue")
    queue.mkdir(mode=0o700, parents=True, exist_ok=True)
    return queue

def remove_after_commit(key: str) -> None:
    # Keys are generated by the server, never arbitrary user paths.
    if not source_images.KEY.fullmatch(key):
        logger.error("account_upload_cleanup_invalid_key")
        return
    try:
        source_images.remove_file(key)
    except OSError:
        try:
            path = queue_dir() / key
            if path.is_symlink():
                raise ValueError("Invalid cleanup marker")
            with path.open("ab") as marker:
                path.chmod(0o600)
                marker.flush()
        except (OSError, ValueError):
            logger.critical("account_upload_cleanup_queue_failed")
        logger.warning("account_upload_cleanup_retry_queued")
    except ValueError:
        logger.error("account_upload_cleanup_invalid_path")

def retry_pending() -> None:
    root = source_images.ROOT.resolve()
    queue = root / ".deletion-pending"
    if not queue.exists() or queue.is_symlink():
        return
    for marker in list(queue.iterdir())[:100]:
        if marker.is_symlink() or not source_images.KEY.fullmatch(marker.name):
            continue
        try:
            source_images.remove_file(marker.name)
            marker.unlink(missing_ok=True)
        except (OSError, ValueError):
            logger.warning("account_upload_cleanup_retry_pending")
